-- Generated by `npm run db:report-functions` from the report files; don't edit by hand.
-- Every report as a function that runs as the person asking, so the access rules
-- (row-level security) decide which rows it reads. Each row comes back as JSON,
-- with its columns in the report's order.

-- Rep scorecard by month (src/db/queries/postgres/1-rep-scorecard.sql)
CREATE OR REPLACE FUNCTION public.report_rep_scorecard() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH ups_by_month AS (
  SELECT rep_id,
         to_char(visited_on, 'YYYY-MM') AS month,  -- the date 2026-04-17 → '2026-04'
         COUNT(*)                 AS ups
  FROM visits
  GROUP BY rep_id, month
),
sales_by_month AS (
  SELECT rep_id,
         to_char(closed_on, 'YYYY-MM') AS month,
         COUNT(*)                AS orders,
         SUM(topline_cents)      AS topline_cents,
         SUM(gross_cents)        AS gross_cents,
         SUM(CASE WHEN attach THEN 1 ELSE 0 END) AS base_orders,
         SUM(commission_cents)   AS commission_cents
  FROM deals
  GROUP BY rep_id, month
)
SELECT u.month,
       r.name                                                  AS rep,
       u.ups,
       COALESCE(s.orders, 0)                                   AS orders,
       ROUND(100.0 * COALESCE(s.orders, 0) / u.ups, 1)         AS conversion_pct,
       ROUND(COALESCE(s.topline_cents, 0) / 100.0, 2)          AS topline,
       ROUND(s.topline_cents / 100.0 / s.orders, 2)            AS avg_order,
       ROUND(100.0 * s.gross_cents / s.topline_cents, 1)       AS margin_pct,
       ROUND(100.0 * s.base_orders / s.orders, 1)              AS base_attach_pct,
       ROUND(COALESCE(s.commission_cents, 0) / 100.0, 2)       AS commission,
       ROUND(100.0 * s.commission_cents / s.topline_cents, 2)  AS comp_pct
FROM ups_by_month u
JOIN reps r ON r.id = u.rep_id
LEFT JOIN sales_by_month s ON s.rep_id = u.rep_id AND s.month = u.month
ORDER BY u.month, r.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_rep_scorecard() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_rep_scorecard() TO authenticated;

-- Store comparison (src/db/queries/postgres/2-store-comparison.sql)
CREATE OR REPLACE FUNCTION public.report_store_comparison() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH ups_by_store AS (
  SELECT store_id, COUNT(*) AS ups
  FROM visits
  GROUP BY store_id
),
sales_by_store AS (
  SELECT store_id,
         COUNT(DISTINCT rep_id) AS reps,
         COUNT(*)               AS orders,
         SUM(topline_cents)     AS topline_cents,
         SUM(gross_cents)       AS gross_cents,
         SUM(CASE WHEN attach THEN 1 ELSE 0 END) AS base_orders,
         SUM(commission_cents)  AS commission_cents
  FROM deals
  GROUP BY store_id
)
SELECT st.name                                                 AS store,
       s.reps,
       u.ups,
       s.orders,
       ROUND(100.0 * s.orders / u.ups, 1)                      AS conversion_pct,
       ROUND(s.topline_cents / 100.0, 2)                       AS topline,
       ROUND(s.topline_cents / 100.0 / s.orders, 2)            AS avg_order,
       ROUND(100.0 * s.gross_cents / s.topline_cents, 1)       AS margin_pct,
       ROUND(100.0 * s.base_orders / s.orders, 1)              AS base_attach_pct,
       ROUND(s.commission_cents / 100.0, 2)                    AS commission,
       ROUND(100.0 * s.commission_cents / s.topline_cents, 2)  AS comp_pct
FROM stores st
JOIN ups_by_store u   ON u.store_id = st.id
JOIN sales_by_store s ON s.store_id = st.id
ORDER BY topline DESC
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_store_comparison() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_store_comparison() TO authenticated;

-- Tier mix by rep (src/db/queries/3-tier-mix.sql)
CREATE OR REPLACE FUNCTION public.report_tier_mix() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT r.name                                                               AS rep,
       COUNT(*)                                                             AS orders,
       ROUND(100.0 * SUM(CASE WHEN d.tier_id = 'top'    THEN 1 ELSE 0 END) / COUNT(*), 1) AS top_pct,
       ROUND(100.0 * SUM(CASE WHEN d.tier_id = 'middle' THEN 1 ELSE 0 END) / COUNT(*), 1) AS middle_pct,
       ROUND(100.0 * SUM(CASE WHEN d.tier_id = 'low'    THEN 1 ELSE 0 END) / COUNT(*), 1) AS low_pct,
       ROUND(AVG(d.offers_made), 2)                                         AS avg_offers,
       ROUND(100.0 * SUM(d.list_topline_cents - d.topline_cents) / SUM(d.list_topline_cents), 1)
                                                                            AS discount_pct
FROM deals d
JOIN reps r ON r.id = d.rep_id
GROUP BY r.id, r.name
ORDER BY low_pct DESC
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_tier_mix() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_tier_mix() TO authenticated;

-- Where deals close on the ladder (src/db/queries/4-where-deals-close.sql)
CREATE OR REPLACE FUNCTION public.report_where_deals_close() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT closed_at_rung,
       COUNT(*)                                                  AS deals,
       ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1)        AS share_pct,
       ROUND(AVG(topline_cents) / 100.0, 2)                      AS avg_price,
       ROUND(100.0 * SUM(list_topline_cents - topline_cents) / SUM(list_topline_cents), 1)
                                                                 AS discount_pct,
       ROUND(AVG(margin_bp) / 100.0, 1)                          AS avg_margin_pct,
       ROUND(AVG(commission_cents) / 100.0, 2)                   AS avg_commission
FROM deals
GROUP BY closed_at_rung
ORDER BY closed_at_rung
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_where_deals_close() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_where_deals_close() TO authenticated;

-- Adjustable-base attach by month (src/db/queries/postgres/5-attach-trend.sql)
CREATE OR REPLACE FUNCTION public.report_attach_trend() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH monthly AS (
  SELECT to_char(closed_on, 'YYYY-MM')              AS month,
         COUNT(*)                                   AS orders,
         SUM(CASE WHEN attach THEN 1 ELSE 0 END)    AS base_orders,
         ROUND(100.0 * SUM(CASE WHEN attach THEN 1 ELSE 0 END) / COUNT(*), 1) AS attach_pct
  FROM deals
  GROUP BY month
)
SELECT month,
       orders,
       base_orders,
       attach_pct,
       ROUND(attach_pct - LAG(attach_pct) OVER (ORDER BY month), 1) AS change_pts
FROM monthly
ORDER BY month
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_attach_trend() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_attach_trend() TO authenticated;

-- Premium line by rep (src/db/queries/postgres/6-premium-share.sql)
CREATE OR REPLACE FUNCTION public.report_premium_share() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH mattress_dollars AS (
  SELECT d.rep_id,
         SUM(dl.net_cents)                                          AS all_mattress_cents,
         SUM(CASE WHEN dl.locked THEN dl.net_cents ELSE 0 END)      AS premium_mattress_cents
  FROM deals d
  JOIN deal_lines dl ON dl.deal_id = d.id
  JOIN products p    ON p.sku = dl.sku
  WHERE p.category = 'mattress'
  GROUP BY d.rep_id
),
premium_sales AS (
  SELECT d.id, d.rep_id, d.gross_cents, d.topline_cents
  FROM deals d
  WHERE EXISTS (
    SELECT 1
    FROM deal_lines dl
    JOIN products p ON p.sku = dl.sku
    WHERE dl.deal_id = d.id AND dl.locked AND p.category = 'mattress'
  )
),
premium_by_rep AS (
  SELECT rep_id,
         COUNT(*)            AS premium_sales,
         SUM(gross_cents)    AS gross_cents,
         SUM(topline_cents)  AS topline_cents
  FROM premium_sales
  GROUP BY rep_id
),
add_ons_by_rep AS (
  SELECT ps.rep_id,
         SUM(dl.net_cents) AS add_on_cents
  FROM premium_sales ps
  JOIN deal_lines dl ON dl.deal_id = ps.id
  JOIN products p    ON p.sku = dl.sku
  WHERE p.category <> 'mattress'
  GROUP BY ps.rep_id
)
SELECT r.name                                                             AS rep,
       COALESCE(pb.premium_sales, 0)                                      AS premium_sales,
       ROUND(100.0 * m.premium_mattress_cents / m.all_mattress_cents, 1)  AS premium_share_pct,
       ROUND(100.0 * pb.gross_cents / pb.topline_cents, 1)                AS premium_margin_pct,
       ROUND(a.add_on_cents / 100.0 / pb.premium_sales, 2)                AS avg_add_ons
FROM reps r
JOIN mattress_dollars m     ON m.rep_id = r.id
LEFT JOIN premium_by_rep pb ON pb.rep_id = r.id
LEFT JOIN add_ons_by_rep a  ON a.rep_id = r.id
ORDER BY premium_share_pct DESC
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_premium_share() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_premium_share() TO authenticated;

-- Exceptions: low-margin sales (src/db/queries/postgres/7-exceptions.sql)
CREATE OR REPLACE FUNCTION public.report_exceptions() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH rules AS (
  SELECT (settings_json ->> 'exceptionMarginBp')::int AS exception_bp
  FROM settings_history
  ORDER BY id DESC
  LIMIT 1
),
per_rep AS (
  SELECT d.rep_id,
         COUNT(*)                                                     AS orders,
         SUM(CASE WHEN d.tier_id = 'low' THEN 1 ELSE 0 END)           AS low_tier_sales,
         SUM(CASE WHEN d.margin_bp < rules.exception_bp THEN 1 ELSE 0 END) AS under_margin_sales,
         MAX(CASE WHEN d.margin_bp < rules.exception_bp THEN d.closed_on END) AS last_under_margin
  FROM deals d
  CROSS JOIN rules
  GROUP BY d.rep_id
)
SELECT r.name                                                  AS rep,
       COALESCE(p.orders, 0)                                   AS orders,
       COALESCE(p.low_tier_sales, 0)                           AS low_tier_sales,
       ROUND(100.0 * p.low_tier_sales / p.orders, 1)           AS low_tier_pct,
       COALESCE(p.under_margin_sales, 0)                        AS under_margin_sales,
       ROUND(100.0 * p.under_margin_sales / p.orders, 1)        AS under_margin_pct,
       p.last_under_margin
FROM reps r
LEFT JOIN per_rep p ON p.rep_id = r.id
ORDER BY under_margin_sales DESC, low_tier_pct DESC
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_exceptions() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_exceptions() TO authenticated;

-- The company by month (src/db/queries/postgres/usage/1-company-by-month.sql)
CREATE OR REPLACE FUNCTION public.report_usage_company_by_month() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH store_count AS (
  SELECT to_char(day, 'YYYY-MM') AS month,          -- the date 2026-04-17 → '2026-04'
         SUM(ups)                AS customers,
         COUNT(DISTINCT rep_id)  AS reps_on_floor
  FROM traffic
  WHERE ups > 0
  GROUP BY month
),
app_log AS (
  SELECT to_char(at, 'YYYY-MM') AS month,
         SUM(CASE WHEN type = 'ticket_started'   THEN 1 ELSE 0 END)  AS tickets,
         COUNT(DISTINCT CASE WHEN type = 'ticket_started' THEN rep_id END) AS reps_using,
         SUM(CASE WHEN type = 'outcome_recorded' THEN 1 ELSE 0 END)  AS outcomes,
         SUM(CASE WHEN type = 'ticket_abandoned' THEN 1 ELSE 0 END)  AS dropped
  FROM events
  GROUP BY month
)
SELECT s.month,
       s.customers,
       COALESCE(a.tickets, 0)                         AS tickets,
       ROUND(100.0 * COALESCE(a.tickets, 0) / s.customers, 1) AS coverage_pct,
       s.reps_on_floor,
       COALESCE(a.reps_using, 0)                      AS reps_using,
       ROUND(100.0 * a.outcomes / a.tickets, 1)       AS outcome_pct,
       ROUND(100.0 * a.dropped / a.tickets, 1)        AS dropped_pct
FROM store_count s
LEFT JOIN app_log a ON a.month = s.month
ORDER BY s.month
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_company_by_month() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_company_by_month() TO authenticated;

-- Each store by week (src/db/queries/postgres/usage/2-stores-by-week.sql)
CREATE OR REPLACE FUNCTION public.report_usage_stores_by_week() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH store_count AS (
  SELECT store_id,
         CAST(date_trunc('week', day) AS DATE) AS week,
         SUM(ups)                          AS customers,
         COUNT(DISTINCT rep_id)            AS reps_on_floor
  FROM traffic
  WHERE ups > 0
  GROUP BY store_id, week
),
app_log AS (
  SELECT store_id,
         CAST(date_trunc('week', at) AS DATE) AS week,
         COUNT(DISTINCT CASE WHEN type = 'ticket_started' THEN rep_id END) AS reps_using,
         SUM(CASE WHEN type = 'session_started' THEN 1 ELSE 0 END)        AS sittings,
         SUM(CASE WHEN type = 'ticket_started'  THEN 1 ELSE 0 END)        AS tickets
  FROM events
  GROUP BY store_id, week
)
SELECT s.week,
       st.name                                 AS store,
       s.reps_on_floor,
       COALESCE(a.reps_using, 0)               AS reps_using,
       COALESCE(a.sittings, 0)                 AS sittings,
       s.customers,
       COALESCE(a.tickets, 0)                  AS tickets,
       ROUND(100.0 * COALESCE(a.tickets, 0) / s.customers, 1) AS coverage_pct
FROM store_count s
JOIN stores st ON st.id = s.store_id
LEFT JOIN app_log a ON a.store_id = s.store_id AND a.week = s.week
ORDER BY s.week, st.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_stores_by_week() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_stores_by_week() TO authenticated;

-- Coverage by rep and month (src/db/queries/postgres/usage/3-coverage-by-rep.sql)
CREATE OR REPLACE FUNCTION public.report_usage_coverage() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH store_count AS (
  SELECT rep_id,
         to_char(day, 'YYYY-MM') AS month,
         SUM(ups)          AS customers
  FROM traffic
  GROUP BY rep_id, month
),
tickets AS (
  SELECT rep_id,
         to_char(at, 'YYYY-MM') AS month,
         COUNT(*)         AS tickets
  FROM events
  WHERE type = 'ticket_started'
  GROUP BY rep_id, month
)
SELECT r.name                                   AS rep,
       s.month,
       s.customers,
       COALESCE(t.tickets, 0)                   AS tickets,
       ROUND(100.0 * COALESCE(t.tickets, 0) / s.customers, 1) AS coverage_pct,
       s.customers - COALESCE(t.tickets, 0)     AS no_ticket
FROM store_count s
JOIN reps r ON r.id = s.rep_id
LEFT JOIN tickets t ON t.rep_id = s.rep_id AND t.month = s.month
WHERE s.customers > 0
ORDER BY r.name, s.month
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_coverage() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_coverage() TO authenticated;

-- What happens to each ticket (src/db/queries/usage/4-ticket-funnel.sql)
CREATE OR REPLACE FUNCTION public.report_usage_funnel() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH ticket AS (
  SELECT ticket_id,
         MAX(CASE WHEN type = 'ticket_started'   THEN rep_id END)          AS rep_id,
         MAX(CASE WHEN type = 'discount_applied' THEN 1 ELSE 0 END)        AS tried_price,
         MAX(CASE WHEN type = 'offer_recorded'   THEN 1 ELSE 0 END)        AS recorded_offer,
         MAX(CASE WHEN type = 'outcome_recorded' AND how = 'bought' THEN 1 ELSE 0 END) AS bought,
         MAX(CASE WHEN type = 'outcome_recorded' AND how = 'walked' THEN 1 ELSE 0 END) AS walked,
         MAX(CASE WHEN type = 'ticket_abandoned' THEN 1 ELSE 0 END)        AS dropped
  FROM events
  WHERE ticket_id IS NOT NULL
  GROUP BY ticket_id
)
SELECT r.name                                              AS rep,
       COUNT(*)                                            AS tickets,
       ROUND(100.0 * SUM(t.tried_price) / COUNT(*), 1)     AS tried_price_pct,
       ROUND(100.0 * SUM(t.recorded_offer) / COUNT(*), 1)  AS recorded_offer_pct,
       SUM(t.bought)                                       AS bought,
       SUM(t.walked)                                       AS walked,
       SUM(t.dropped)                                      AS dropped,
       ROUND(100.0 * (SUM(t.bought) + SUM(t.walked)) / COUNT(*), 1) AS outcome_pct
FROM ticket t
JOIN reps r ON r.id = t.rep_id
GROUP BY r.name
ORDER BY r.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_funnel() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_funnel() TO authenticated;

-- How items get on the ticket (src/db/queries/postgres/usage/5-adding-items.sql)
CREATE OR REPLACE FUNCTION public.report_usage_adding_items() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT r.name                                                             AS rep,
       to_char(e.at, 'YYYY-MM')                                           AS month,
       COUNT(*)                                                           AS items,
       ROUND(100.0 * SUM(CASE WHEN e.how = 'sku'       THEN 1 ELSE 0 END) / COUNT(*), 1) AS sku_pct,
       ROUND(100.0 * SUM(CASE WHEN e.how = 'search'    THEN 1 ELSE 0 END) / COUNT(*), 1) AS search_pct,
       ROUND(100.0 * SUM(CASE WHEN e.how = 'lookup'    THEN 1 ELSE 0 END) / COUNT(*), 1) AS lookup_pct,
       ROUND(100.0 * SUM(CASE WHEN e.how = 'inventory' THEN 1 ELSE 0 END) / COUNT(*), 1) AS inventory_pct
FROM events e
JOIN reps r ON r.id = e.rep_id
WHERE e.type = 'item_added'
GROUP BY r.name, month
ORDER BY r.name, month
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_adding_items() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_adding_items() TO authenticated;

-- How prices get changed (src/db/queries/usage/6-price-changes.sql)
CREATE OR REPLACE FUNCTION public.report_usage_price_changes() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH counts AS (
  SELECT rep_id,
         SUM(CASE WHEN type = 'discount_applied' THEN 1 ELSE 0 END)                         AS changes,
         SUM(CASE WHEN type = 'discount_applied' AND how = 'new_price' THEN 1 ELSE 0 END)   AS new_price,
         SUM(CASE WHEN type = 'discount_applied' AND how = 'percent' THEN 1 ELSE 0 END)     AS percent,
         SUM(CASE WHEN type = 'discount_applied' AND how = 'dollars' THEN 1 ELSE 0 END)     AS dollars,
         SUM(CASE WHEN type = 'discount_applied' AND scope = 'row' THEN 1 ELSE 0 END)       AS one_row,
         SUM(CASE WHEN type = 'discount_applied' AND scope = 'ticket' THEN 1 ELSE 0 END)    AS whole_ticket,
         SUM(CASE WHEN type = 'discount_applied' AND scope = 'delivery' THEN 1 ELSE 0 END)  AS delivery,
         SUM(CASE WHEN type = 'floor_refused' THEN 1 ELSE 0 END)                            AS refused,
         SUM(CASE WHEN type = 'ticket_started' THEN 1 ELSE 0 END)                           AS tickets
  FROM events
  GROUP BY rep_id
)
SELECT r.name                                                  AS rep,
       c.changes                                               AS price_changes,
       ROUND(100.0 * c.new_price    / NULLIF(c.changes, 0), 1) AS new_price_pct,
       ROUND(100.0 * c.percent      / NULLIF(c.changes, 0), 1) AS percent_pct,
       ROUND(100.0 * c.dollars      / NULLIF(c.changes, 0), 1) AS dollars_pct,
       ROUND(100.0 * c.one_row      / NULLIF(c.changes, 0), 1) AS one_row_pct,
       ROUND(100.0 * c.whole_ticket / NULLIF(c.changes, 0), 1) AS whole_ticket_pct,
       ROUND(100.0 * c.delivery     / NULLIF(c.changes, 0), 1) AS delivery_pct,
       ROUND(100.0 * c.refused      / NULLIF(c.tickets, 0), 1) AS refused_per_100
FROM counts c
JOIN reps r ON r.id = c.rep_id
ORDER BY r.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_price_changes() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_price_changes() TO authenticated;

-- Scratchpad signals (src/db/queries/postgres/usage/7-scratchpad.sql)
CREATE OR REPLACE FUNCTION public.report_usage_scratchpad() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH ticket AS (
  SELECT ticket_id,
         MAX(CASE WHEN type = 'ticket_started'       THEN rep_id END)  AS rep_id,
         MIN(CASE WHEN type = 'ticket_started'       THEN at END)      AS started_at,
         MIN(CASE WHEN type = 'discount_applied'     THEN at END)      AS first_price_at,
         SUM(CASE WHEN type = 'discount_applied'     THEN 1 ELSE 0 END) AS changes,
         SUM(CASE WHEN type = 'offer_recorded'       THEN 1 ELSE 0 END) AS offers,
         SUM(CASE WHEN type = 'gm_calculator_opened' THEN 1 ELSE 0 END) AS gm_opens
  FROM events
  WHERE ticket_id IS NOT NULL
  GROUP BY ticket_id
)
SELECT r.name                                                 AS rep,
       COUNT(*)                                               AS tickets,
       ROUND(1.0 * SUM(t.changes) / COUNT(*), 1)              AS changes_per_ticket,
       ROUND(1.0 * SUM(t.offers) / COUNT(*), 2)               AS offers_per_ticket,
       ROUND(1.0 * SUM(t.changes) / NULLIF(SUM(t.offers), 0), 1) AS changes_per_offer,
       ROUND(AVG(EXTRACT(EPOCH FROM t.first_price_at - t.started_at) / 60), 1) AS minutes_to_first_price,
       ROUND(100.0 * SUM(t.gm_opens) / COUNT(*), 1)           AS gm_opens_per_100
FROM ticket t
JOIN reps r ON r.id = t.rep_id
GROUP BY r.name
ORDER BY r.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_scratchpad() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_scratchpad() TO authenticated;

-- Data quality (src/db/queries/usage/8-data-quality.sql)
CREATE OR REPLACE FUNCTION public.report_usage_data_quality() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH store_count AS (
  SELECT rep_id, SUM(ups) AS customers
  FROM traffic
  GROUP BY rep_id
),
app_log AS (
  SELECT rep_id,
         SUM(CASE WHEN type = 'ticket_started' THEN 1 ELSE 0 END)                      AS tickets,
         SUM(CASE WHEN type = 'outcome_recorded' THEN 1 ELSE 0 END)                    AS recorded,
         SUM(CASE WHEN type = 'outcome_recorded' AND how = 'walked' THEN 1 ELSE 0 END) AS walked,
         SUM(CASE WHEN type = 'ticket_abandoned' THEN 1 ELSE 0 END)                    AS dropped
  FROM events
  GROUP BY rep_id
)
SELECT r.name                                                     AS rep,
       s.customers,
       a.recorded,
       ROUND(100.0 * a.recorded / s.customers, 1)                 AS seen_pct,
       s.customers - a.tickets                                    AS no_ticket,
       a.dropped,
       ROUND(100.0 * a.walked / NULLIF(a.walked + a.dropped, 0), 1) AS walkouts_recorded_pct
FROM store_count s
JOIN reps r ON r.id = s.rep_id
JOIN app_log a ON a.rep_id = s.rep_id
ORDER BY r.name
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_usage_data_quality() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_usage_data_quality() TO authenticated;

-- Offers accepted by discount size (src/db/queries/patterns/1-discount-size.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_discount_size() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT CASE WHEN discount_pct < 10 THEN 'Under 10%'
            WHEN discount_pct < 15 THEN '10–15%'
            WHEN discount_pct < 20 THEN '15–20%'
            WHEN discount_pct < 30 THEN '20–30%'
            ELSE '30% or more' END                    AS discount,
       COUNT(*)                                       AS offers,
       SUM(accepted)                                  AS accepted,
       ROUND(100.0 * SUM(accepted) / COUNT(*), 1)     AS accepted_pct,
       CASE WHEN COUNT(*) < 30 THEN 'too few to trust' END AS note
FROM offer_facts
WHERE step_no > 0
GROUP BY discount
ORDER BY MIN(discount_pct)
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_discount_size() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_discount_size() TO authenticated;

-- Offers accepted by base discount (src/db/queries/patterns/2-base-discount.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_base_discount() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT CASE WHEN base_cut_pct < 15 THEN 'Under 15% (or none)'
            WHEN base_cut_pct < 35 THEN '15–35%'
            ELSE '35% or more' END                    AS off_the_base,
       COUNT(*)                                       AS offers,
       SUM(accepted)                                  AS accepted,
       ROUND(100.0 * SUM(accepted) / COUNT(*), 1)     AS accepted_pct,
       CASE WHEN COUNT(*) < 30 THEN 'too few to trust' END AS note
FROM offer_facts
WHERE step_no > 0 AND base_cut_pct IS NOT NULL
GROUP BY off_the_base
ORDER BY MIN(base_cut_pct)
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_base_discount() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_base_discount() TO authenticated;

-- Offers accepted by delivery (src/db/queries/patterns/3-free-delivery.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_free_delivery() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT CASE WHEN asking_cents >= 250000 THEN 'Big ($2,500+)' ELSE 'Under $2,500' END AS ticket,
       CASE delivery WHEN 'waived'  THEN 'Free (waived)'
                     WHEN 'charged' THEN 'Charged'
                     WHEN 'basic'   THEN 'Basic tier (always free)'
                     ELSE 'Took it home' END          AS delivery_on_offer,
       COUNT(*)                                       AS offers,
       ROUND(100.0 * SUM(accepted) / COUNT(*), 1)     AS accepted_pct,
       CASE WHEN COUNT(*) < 30 THEN 'too few to trust' END AS note
FROM offer_facts
WHERE step_no > 0
GROUP BY ticket, delivery_on_offer
ORDER BY ticket, accepted_pct DESC, delivery_on_offer
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_free_delivery() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_free_delivery() TO authenticated;

-- Close rate by financing term (src/db/queries/patterns/4-financing.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_financing() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT CASE WHEN financing_months IS NULL THEN 'None'
            WHEN financing_months < 36 THEN CAST(financing_months AS TEXT) || ' months'
            ELSE '36 months or more' END              AS financing,
       COUNT(*)                                       AS customers,
       SUM(bought)                                    AS bought,
       ROUND(100.0 * SUM(bought) / COUNT(*), 1)       AS close_pct,
       CASE WHEN COUNT(*) < 30 THEN 'too few to trust' END AS note
FROM offer_facts
WHERE step_no = 0
GROUP BY financing
ORDER BY MIN(COALESCE(financing_months, 0))
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_financing() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_financing() TO authenticated;

-- What changed after a "no" (src/db/queries/patterns/5-second-offers.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_second_offers() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH last_step AS (
  SELECT visit_id, MAX(step_no) AS step_no
  FROM offer_facts
  GROUP BY visit_id
)
SELECT CASE WHEN l.bought = 1 THEN 'Bought on a later offer' ELSE 'Walked anyway' END AS outcome,
       COUNT(*)                                                      AS customers,
       ROUND(AVG(l.discount_pct - f.discount_pct), 1)                AS extra_discount_pts,
       ROUND(100.0 * SUM(CASE WHEN f.delivery = 'charged' AND l.delivery = 'waived' THEN 1 ELSE 0 END) / COUNT(*), 1)
                                                                     AS delivery_made_free_pct,
       ROUND(100.0 * SUM(CASE WHEN l.base_cut_pct > f.base_cut_pct THEN 1 ELSE 0 END) / COUNT(*), 1)
                                                                     AS more_off_base_pct
FROM offer_facts f
JOIN last_step s   ON s.visit_id = f.visit_id
JOIN offer_facts l ON l.visit_id = f.visit_id AND l.step_no = s.step_no
WHERE f.step_no = 1
  AND f.accepted = 0
  AND l.step_no > 1
GROUP BY outcome
ORDER BY outcome
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_second_offers() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_second_offers() TO authenticated;

-- Commission given up to discounting (src/db/queries/patterns/6-commission-given-up.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_commission_given_up() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
SELECT r.name                                                      AS rep,
       COUNT(*)                                                    AS sales,
       ROUND(SUM(a.commission_cents) / 100.0, 2)                   AS commission_at_asking,
       ROUND(SUM(d.commission_cents) / 100.0, 2)                   AS commission,
       ROUND(SUM(a.commission_cents - d.commission_cents) / 100.0, 2) AS given_up,
       ROUND(100.0 * SUM(a.commission_cents - d.commission_cents) / SUM(a.commission_cents), 1) AS given_up_pct,
       ROUND(SUM(a.commission_cents - d.commission_cents) / 100.0 / COUNT(*), 2) AS given_up_per_sale
FROM deals d
JOIN offers a ON a.visit_id = d.visit_id AND a.step_no = 0
JOIN reps r   ON r.id = d.rep_id
GROUP BY r.name
ORDER BY given_up_pct DESC, rep
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_commission_given_up() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_commission_given_up() TO authenticated;

-- Offered vs sold, by product type (src/db/queries/patterns/7-offered-vs-sold.sql)
CREATE OR REPLACE FUNCTION public.report_patterns_offered_vs_sold() RETURNS SETOF json
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $report$
SELECT row_to_json(r) FROM (
WITH offered AS (
  SELECT p.category, COUNT(DISTINCT o.visit_id) AS customers
  FROM offers o
  JOIN offer_lines l ON l.offer_id = o.id
  JOIN products p    ON p.sku = l.sku
  WHERE o.step_no = 0
  GROUP BY p.category
),
sold AS (
  SELECT p.category,
         COUNT(DISTINCT d.visit_id)  AS customers,
         SUM(dl.discount_cents)      AS discount_cents,
         SUM(dl.list_cents)          AS list_cents
  FROM deals d
  JOIN deal_lines dl ON dl.deal_id = d.id
  JOIN products p    ON p.sku = dl.sku
  GROUP BY p.category
)
SELECT o.category,
       o.customers,
       COALESCE(s.customers, 0)                                   AS bought,
       ROUND(100.0 * COALESCE(s.customers, 0) / o.customers, 1)   AS close_pct,
       ROUND(100.0 * s.discount_cents / s.list_cents, 1)          AS discount_pct
FROM offered o
LEFT JOIN sold s ON s.category = o.category
ORDER BY o.customers DESC, o.category
) r
$report$;
REVOKE EXECUTE ON FUNCTION public.report_patterns_offered_vs_sold() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_patterns_offered_vs_sold() TO authenticated;
